/* Exact, local teaching data: generated and verified by build-cube2-case.cjs. */
(() => {
'use strict';
const host=document.getElementById('cube2-worked-example');if(!host)return;
const D=window.Cube2CaseData;if(!D){host.innerHTML='<p class="case-error">The worked-example data could not load. Reload this page to try again.</p>';return;}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const word=w=>w.length?w.map(i=>D.moves[i].name).join(' '):'I (no moves)';
const fmt=n=>Number(n).toLocaleString('en-US');
const nontrivial=D.levels.filter(l=>l.entries.length>1);
const formula=s=>'<div class="case-math">'+s+'</div>';
const panel=(title,body,open=false)=>`<details${open?' open':''}><summary>${title}</summary><div class="case-body">${body}</div></details>`;
const code=s=>'<pre>'+esc(s)+'</pre>';
const table=(heads,rows)=>`<div class="case-scroll" tabindex="0"><table><thead><tr>${heads.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
function cycles(p){const seen=new Set(),out=[];for(let q=0;q<p.length;q++){if(seen.has(q))continue;const c=[];let r=q;do{seen.add(r);c.push(r);r=p[r];}while(r!==q);if(c.length>1)out.push('('+c.join(' ') +')');}return out.join(' ')||'I';}
function matrixHTML(p,fixed=[]){const F=new Set(fixed);return `<div class="case-scroll" tabindex="0"><table class="case-matrix" aria-label="24 by 24 permutation matrix; rows are destinations, columns are sources"><thead><tr><th>↓ / →</th>${p.map((_,i)=>'<th scope="col">'+i+'</th>').join('')}</tr></thead><tbody>${p.map((_,r)=>'<tr><th scope="row">'+r+'</th>'+p.map((v,c)=>`<td class="${v===r?(F.has(c)?'one fixed':'one'):''}" title="row ${r}, column ${c}">${v===r?1:0}</td>`).join('')+'</tr>').join('')}</tbody></table></div><p class="case-matrix-caption">Column = source. Row = destination. Light cells are 1; all other cells are 0.${F.size?' Gray diagonal 1s are the already fixed base locations.':''}</p>`;}
function inspectHTML(t,fixed=[]){return `<p class="case-word"><strong>Playback:</strong> ${esc(word(t.word))}</p><p class="case-meta">${t.word.length} face turn${t.word.length===1?'':'s'} · ${t.perm.filter((v,i)=>v!==i).length} moved sticker locations</p><p class="case-value"><strong>Cycles:</strong> ${esc(cycles(t.perm))}</p><p class="case-value"><strong>Destination array p[0…23]:</strong> [${t.perm.join(', ')}]</p>${matrixHTML(t.perm,fixed)}`;}
let remaining=BigInt(D.order);
const levelRows=D.levels.map(l=>{const size=remaining;remaining/=BigInt(l.entries.length);return [l.index,'b'+l.index+' = '+l.base,l.index?'0…'+(l.index-1):'None',l.entries.length,fmt(size),Math.max(...l.entries.map(t=>t.word.length))];});
const nodeRows=D.nodes.map(n=>[n.index,esc(n.id),`<span class="case-swatch" style="background:${esc(n.color)}"></span>${esc(n.color)}`,'('+n.center.join(', ')+')','('+n.normal.join(', ')+')']);
const example=D.example;
host.classList.add('cube2-case');
host.innerHTML=`<h2>The 2×2×2, worked completely</h2><p>Start with 24 sticker locations and 18 legal face turns. A small table of legal transporter words factors every reachable labeled configuration. This case uses the <em>actual matrices and complete stabilizer cache shipped with Puzzle Atlas</em>, not a simplified substitute.</p><p class="case-note">There are infinitely many equivalent move words: insert U U′ anywhere, for example. “Complete” here means every primitive matrix and every representative in one finite, complete stabilizer chain. All ${D.certificate.transporterWords} non-identity representatives are available below, with their full words and matrices. It does not mean listing infinitely many words or promising shortest solutions.</p>
${panel('1 · State, dimensions, coordinates and move convention',`
<p>Ω = {0,…,23} indexes fixed locations. A sticker identity has a home address q; its current address is g[q]. The source-to-destination array g has 24 integers. Its matrix G has 24 × 24 entries, with <strong>G[g[q],q] = 1</strong> and every other entry in column q zero. Camera movement changes neither addresses nor G.</p>
${formula('<math display="block"><mrow><msub><mi>x</mi><mi>current</mi></msub><mo>=</mo><mi>G</mi><msub><mi>x</mi><mi>solved</mi></msub><mo>,</mo><mspace width="1em"/><mi>G</mi><mo>∈</mo><msup><mrow><mo>{</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>}</mo></mrow><mrow><mn>24</mn><mo>×</mo><mn>24</mn></mrow></msup><mo>,</mo><mspace width="1em"/><msup><mi>G</mi><mtext>T</mtext></msup><mi>G</mi><mo>=</mo><mi>I</mi></mrow></math>')}
<p>A color state can be a length-24 vector of six color IDs, or a 24 × 6 one-hot matrix X with X[q,c] = 1 for the color c at q. Then X′ = P X. For exact labeled factorization, use G or the 24 unique sticker IDs; equal colors alone do not uniquely identify G. The 24 × 24 matrices are <em>not</em> transition matrices indexed by millions of configurations.</p>
<p>Coordinates use x right, y up, z front. Each corner center has coordinates ±1; its three stickers have outward unit normals. A turn of face F rotates centers and normals in that outer layer clockwise as viewed from outside F. Formally use a right-handed rotation of −π/2 about F’s outward normal, then look up the resulting (center, normal) address. Half and inverse turns are powers P² and P³. A face turn, half turn or inverse turn each costs one here.</p>
${table(['q','Engine address','Home color','Corner center','Face normal'],nodeRows)}
<p>Word tokens are written in execution order, left to right. The corresponding column-vector matrix product has the rightmost action first:</p>
${formula('<math display="block"><mrow><mtext>word </mtext><mo>[</mo><mi>U</mi><mo>,</mo><mi>R</mi><mo>,</mo><msup><mi>F</mi><mn>2</mn></msup><mo>]</mo><mspace width="1em"/><mo>↔</mo><mspace width="1em"/><mi>G</mi><mo>=</mo><msubsup><mi>P</mi><mi>F</mi><mn>2</mn></msubsup><msub><mi>P</mi><mi>R</mi></msub><msub><mi>P</mi><mi>U</mi></msub></mrow></math>')}
${code('THEN(a,b)[q] = b[a[q]]        # execute a, then b\nINVERSE(a)[a[q]] = q\nEVALUATE(word):\n    p = [0,1,...,23]\n    for move in word: p = THEN(p, move.permutation)\n    return p')}
`)}
${panel('2 · All 18 legal permutation matrices',`<p>The six quarter turns generate the group. The actual move vocabulary also contains their inverses and half turns. Each matrix below is shown in full; its 24-entry destination array is an exact sparse representation of the same matrix.</p><div class="case-controls"><label for="case-move">Primitive move</label><select id="case-move">${D.moves.map((m,i)=>`<option value="${i}">${esc(m.name)} · order ${m.order}</option>`).join('')}</select></div><div id="case-move-output"></div>`)}
${panel('3 · The entire stabilizer chain and every transporter',`
<p>Let H₀ = ⟨U,D,L,R,F,B⟩. Choose bᵢ = i and define Hᵢ = {g ∈ H₀ : g[0] = 0,…,g[i−1] = i−1}. Thus Hᵢ₊₁ fixes one more labeled location. At level i, a transporter Tᵢ,q ∈ Hᵢ sends bᵢ to q and fixes the previous base locations. Tᵢ,bᵢ = I.</p>
<p>Only seven levels have nontrivial orbits. Fixing one sticker also fixes the orientation and position of its whole corner; the last corner is then forced by the remaining position and total-twist constraint. Redundant levels 7–23 are kept in the actual cache so the base contains every location.</p>
${table(['Level i','New base','Previously fixed','Orbit size','|Hᵢ|','Longest word'],levelRows)}
${formula('<math display="block"><mrow><mo>|</mo><msub><mi>H</mi><mn>0</mn></msub><mo>|</mo><mo>=</mo><mn>24</mn><mo>·</mo><mn>21</mn><mo>·</mo><mn>18</mn><mo>·</mo><mn>15</mn><mo>·</mo><mn>12</mn><mo>·</mo><mn>9</mn><mo>·</mo><mn>6</mn><mo>=</mo><mn>'+D.order+'</mn><mo>=</mo><mn>8</mn><mo>!</mo><msup><mn>3</mn><mn>7</mn></msup></mrow></math>')}
<p>This fixed-frame group has ${fmt(D.order)} configurations. Identifying the 24 whole-puzzle orientations gives ${fmt(D.orientationQuotientOrder)} familiar Pocket Cube positions. The factor of 24 is a choice of goal convention, not a different mechanism. [C1]</p>
<div class="case-controls"><label for="case-level">Stabilizer level</label><select id="case-level">${D.levels.map(l=>`<option value="${l.index}">H${l.index} · fixes ${l.index} base location${l.index===1?'':'s'} · orbit ${l.entries.length}</option>`).join('')}</select><label for="case-image">Send base to</label><select id="case-image"></select></div><div id="case-transporter-output"></div>
<p>The union of these representatives is a redundant <em>strong generating set</em>: representatives at levels i and below generate Hᵢ. An individual representative is a legal operation in a stabilizer, not an entire stabilizer subgroup. At each level it is the whole collection, together with the deeper subgroup, that gives full coverage.</p>
`)}
${panel('4 · Factor a configuration and solve it, one exact step at a time',`
<p>Keep a residual permutation R, initially G. At level i find q = R[bᵢ]. Look up Tᵢ,q, then apply its inverse. Because T fixes earlier base locations, this restores bᵢ without disturbing the previously restored base. Holds are endpoint guarantees: intermediate primitive turns may disturb them.</p>
${formula('<math display="block"><mrow><msub><mi>R</mi><mrow><mi>i</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><msubsup><mi>T</mi><mrow><mi>i</mi><mo>,</mo><msub><mi>R</mi><mi>i</mi></msub><mo>[</mo><msub><mi>b</mi><mi>i</mi></msub><mo>]</mo></mrow><mrow><mo>−</mo><mn>1</mn></mrow></msubsup><msub><mi>R</mi><mi>i</mi></msub><mo>,</mo><mspace width="1em"/><msub><mi>R</mi><mn>0</mn></msub><mo>=</mo><mi>G</mi><mo>,</mo><mspace width="1em"/><msub><mi>R</mi><mn>24</mn></msub><mo>=</mo><mi>I</mi></mrow></math>')}
${code('FACTOR-AND-SOLVE(g, levels):\n    r = copy(g); solution = []; factors = []\n    for i = 0,...,23:\n        q = r[i]\n        t = levels[i].transporter[q]\n        if t does not exist: return NOT_IN_LEGAL_GROUP\n        correction = reverse(t.word).map(inverseMove)\n        append correction to solution\n        append t to factors\n        r = THEN(r, INVERSE(t.permutation))\n        assert r[j] == j for every j <= i\n    assert r == identity\n    assert THEN(g, EVALUATE(solution)) == identity\n    return solution, factors')}
<p>In matrix notation G = T₀ T₁ ⋯ T₂₃, omitting identities. To <em>construct</em> G from solved, execute the transporter words in reverse level order. To <em>solve</em> G, execute their inverse words in forward level order. Do not reverse the individual move order without also inverting each move.</p>
<h3>A concrete configuration</h3><p>Scramble in playback order: <code>${esc(word(example.scramble))}</code>.</p><p class="case-value">G’s destination array: [${example.permutation.join(', ')}].</p><p>The cached factorization uses ${example.stages.length} nonempty correction stages and ${example.solution.length} primitive tokens before optional shortening. The inverse scramble is known to be a shorter candidate in this teaching example; the factorizer deliberately uses only G, demonstrating that the move journal is unnecessary.</p>
${example.stages.map(s=>`<div class="case-stage"><h4>Level ${s.level}: restore location ${s.base}</h4><p>R[${s.base}] = ${s.image}. Transporter: <code>${esc(word(s.transporter))}</code>.</p><p>Apply its inverse: <code>${esc(word(s.correction))}</code>.</p><p class="case-value">New residual: [${s.after.join(', ')}]</p><details><summary>Correction matrix and full before/after arrays</summary><div class="case-body"><p class="case-value">Before: [${s.before.join(', ')}]<br>After: [${s.after.join(', ')}]</p>${matrixHTML(s.correctionPerm,D.base.slice(0,s.level))}</div></details></div>`).join('')}
<p><strong>Complete playback:</strong> <code>${esc(word(example.solution))}</code>. The final residual is exactly I. This is a constructive solution, not an optimality certificate.</p>
`)}
${panel('5 · Reproduce and certify the finite tables',`
<p>Start with the 18 primitive arrays above. Give each primitive a word of length one. Build each base-point orbit using the generators that fix earlier base points; store a path to each orbit point. The production builder uses word lengths as Dijkstra edge costs. Complete the chain by adding nonidentity Schreier residues until every required residue sifts to identity.</p>
${code('REPEAT until no generator is added:\n    for each base level i:\n        S_i = current generators fixing 0,...,i-1\n        build orbit O_i of i and transporters T_i[q] under S_i\n    for each level i, each q in O_i, each s in S_i:\n        y = s[q]\n        # execute T_i[q], then s, then inverse(T_i[y])\n        h = THEN(THEN(T_i[q],s),INVERSE(T_i[y]))\n        assert h fixes 0,...,i\n        sift h through levels i+1,...,23\n        if nonidentity residue remains:\n            add residue permutation and its legal word\n            rebuild affected orbits; restart closure\nRETURN all levels once every Schreier residue is identity')}
<p>Why this proves completeness: the Schreier operations generate the next point stabilizer. Completing them recursively makes each deeper subgroup exact. The union of stored transversals reconstructs every legal element, and every stored word consists only of legal primitives. Hence the represented group is neither smaller nor larger than the puzzle’s move group.</p>
<p>This example is generated by <code>scripts/build-cube2-case.cjs</code>. It replays all ${D.certificate.transporterWords} non-identity words and checks their exact matrices, base images and fixed prefixes. It then performs ${fmt(D.certificate.schreierChecks)} orbit/Schreier closure checks using the redundant strong generator set, and sifts all ${D.certificate.primitiveMembershipChecks} primitive moves. These are computations on 24-element arrays, not a traversal of ${fmt(D.order)} states.</p>
<p>The downloadable data include all words explicitly in playback order. The runtime cache compresses repeated subwords in a signed expression DAG: a negative reference reverses the child order and inverts the moves. Both representations evaluate to the same matrices. The shared algorithm chapters explain the DAG, weighted orbit construction, cache validation and limits in full.</p>
<div class="case-links"><a href="cube2-case-data.json" download>Download all example matrices and words (JSON)</a><a href="games/constrained-solver-models/cube2.json">Runtime move model</a><a href="games/constrained-solver-caches/cube2.json">Runtime stabilizer cache</a></div>
`)}
${panel('6 · Color holds, constrained swaps and extension to larger puzzles',`
<p>The preceding chain preserves <em>identities at fixed addresses</em>. A color hold is weaker. With color vector c and held address set H, a legal final permutation p must satisfy c[p⁻¹[h]] = c[h] for every h ∈ H. It may exchange equal-colored stickers. For selected endpoints a and b, require p[a] = b and p[b] = a; other unheld addresses may also move. Held endpoints are temporarily exempted, so the effective hold set is H ∖ {a,b}. They remain visually marked and become held again after the intentional exchange.</p>
<p>Color-hold operations for an arbitrary partially held pattern do not generally form a subgroup: an allowed first operation may change the unheld colors that a second operation draws into a held address. Therefore simply reusing one fixed pointwise stabilizer is safe but restrictive; it is not a complete color-aware solver. Puzzle Atlas combines legal cached words, color-checked witnesses and bounded resumable searches. Every returned word is replayed and checked before animation. An exhausted time budget means <em>unknown</em>, not impossible.</p>
<p>On this puzzle a literal matrix that swaps only two sticker addresses cannot be legal. The three stickers on a corner must stay on one physical corner and preserve its orientation structure; a single sticker transposition violates those constraints. Swapping two whole corners has three coordinated sticker exchanges. A two-node request can still succeed if the necessary collateral changes occur at allowed locations or replace held colors with equal colors. This is why a complete group factorizer does not make every constrained swap possible.</p>
<p>To extend the method: enumerate the new puzzle’s exact sticker/pose addresses; implement and validate each primitive permutation; choose a full base; complete and verify its stabilizer chain; cache legal words and inverse maps; reconstruct current identities from the engine; sift and replay-check. For shape-changing puzzles, model empty pose addresses and orientation information as required. Do not use visible color alone when shape or picture orientation is part of the goal.</p>
<p>For N addresses, r base levels and t stored transporters, explicit transporter arrays cost O(tN) integers, with t ≤ rN; primitives add O(mN). Sifting needs at most r lookups and r compositions of length N: O(rN), excluding output-word expansion. Producing L primitive moves necessarily costs Ω(L). Precomputation also depends on the strong generator count, orbit edges, closure work and word sizes; it has no universal small constant runtime. This fixed 2×2×2 example has N = 24, r = 24 (only 7 nontrivial), m = 18 and ${D.certificate.transporterWords} non-identity transporters. Summing each level’s longest cached word gives a ${D.certificate.rawSolveLengthBound}-move constructive upper bound before cancellations. It is a bound for this cache and fixed-frame goal, not the optimal diameter.</p>
`)}
${panel('Case references and provenance',`<p>[C1] J. Scherphuis, “Mini Cube, the 2×2×2 Rubik’s Cube,” <em>Jaap’s Puzzle Page</em>. <a href="https://www.jaapsch.net/puzzles/cube2.htm" target="_blank" rel="noopener">Puzzle description, state count and human solutions</a>. Accessed Oct. 14, 2026.</p><p>[C2] Puzzle Atlas, <em>2×2×2 move model and verified full-solver cache</em>, model signature <code>${esc(D.modelSignature)}</code>. The matrices, transporter words, closure certificate and worked factorization above are generated directly from these local files. For the general Schreier–Sims, constructive factorization and shortest-path literature, see the handbook’s common references.</p>`)}
`;
const moveSelect=host.querySelector('#case-move'),levelSelect=host.querySelector('#case-level'),imageSelect=host.querySelector('#case-image');
function showMove(){const i=Number(moveSelect.value)||0;host.querySelector('#case-move-output').innerHTML=inspectHTML({word:[i],perm:D.moves[i].perm});}
function showTransporter(){const l=D.levels[Number(levelSelect.value)||0],t=l.entries[Number(imageSelect.value)||0];host.querySelector('#case-transporter-output').innerHTML=inspectHTML(t,l.held);}
function changeLevel(){const l=D.levels[Number(levelSelect.value)||0];imageSelect.innerHTML=l.entries.map((t,i)=>`<option value="${i}">${l.base} → ${t.image}${t.word.length?' · '+t.word.length+' moves':' · identity'}</option>`).join('');imageSelect.value='0';showTransporter();}
moveSelect.addEventListener('change',showMove);levelSelect.addEventListener('change',changeLevel);imageSelect.addEventListener('change',showTransporter);showMove();changeLevel();
})();
